from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];J=R/'judge/kongguan'
hooks={}; cps=[]
def cp(k,e,role='optional'):
 hooks[k]={'type':'js_truthy','expr':e};cps.append({'id':k,'hook':k,'op':'truthy','role':role})
cp('mail_anniversary','JSON.parse(localStorage.getItem("mail_state")||"{}").loggedIn==="hanxiu"')
cp('employee_credential','localStorage.getItem("intranet_login")==="dingwenqian" || (JSON.parse(localStorage.getItem("achievements_state")||"{}").unlocked||[]).includes("main_truth")')
