answers={'q5':'陌生人','q6':'陌生人','q8':'目标','q9':'多维实体','q10':'φ能量','q11':'额外维度中','q16':'onlytruth','q19':'happybirthday','q21':'多维实体','q29':'真相','q31':'生命'}
for k,v in answers.items():
 expr=f'''(()=>{{const a=typeof answers==='object'?answers:JSON.parse(localStorage.getItem('exam_answers')||'{{}}');return String(a[{json.dumps(k)}]||'').toLowerCase().replace(/\\s+/g,'')==={json.dumps(v.lower(),ensure_ascii=False)};}})()'''
 cp('exam_'+k,expr)
cp('exam_q7',"(()=>{const a=typeof answers==='object'?answers:JSON.parse(localStorage.getItem('exam_answers')||'{}');return a.q7===(localStorage.getItem('recommendation_source')==='REF#DAT-2026A05'?'获取情报':'出于善意');})()")
cp('exam_q18',"(()=>{const a=typeof answers==='object'?answers:JSON.parse(localStorage.getItem('exam_answers')||'{}');return ['目标','多维实体','真相','truth'].some(v=>String(a.q18||'').toLowerCase().replace(/\\s+/g,'').includes(v));})()")
cp('exam_q27',"(()=>{const a=typeof answers==='object'?answers:JSON.parse(localStorage.getItem('exam_answers')||'{}');return Array.isArray(a.q27)&&a.q27.length===4&&['健康','财富','自由','尊严'].every(v=>a.q27.includes(v));})()")
cp('exam_all_correct','localStorage.getItem("exam_passed")==="true"','critical')
names={'ordinary':('end01','平凡的一生','e1ordinary.html'),'detective':('end02','不谨慎的侦探','e2detective.html'),'husband':('end03','听话的丈夫','e3funeral.html'),'endless':('end04','没有终点的调查','e3funeral.html'),'truth':('end05','通往真相的路','e3funeral.html')}
for k,(state,name,path) in names.items():
 hooks[k]={'type':'js_truthy','expr':f'''(()=>{{if((typeof isReviewMode==='boolean'&&isReviewMode)||!location.pathname.endsWith({json.dumps(path)})||new URLSearchParams(location.search).has('review'))return false;const e=JSON.parse(localStorage.getItem('endings_unlocked')||'{{}}');return e.{state}===true&&Array.from(document.querySelectorAll('.ending-title,.ending-label')).some(x=>x.textContent.replace(/\\s/g,'').includes({json.dumps('结局·'+name,ensure_ascii=False)})&&x.getBoundingClientRect().height>0&&x.checkVisibility({{checkOpacity:true,checkVisibilityCSS:true}}));}})()'''}
routes=[{'id':k,'tier':'good' if k=='truth' else 'bad' if k in ['ordinary','detective'] else 'normal','gates':['job_identity_referral','exam_all_correct'] if k=='truth' else [],'ending':{'hook':k,'op':'truthy'}} for k in names]
(J/'judge.json').write_text(json.dumps({'hooks':hooks,'checkpoints':cps,'events':{},'routes':routes,'ending':{'hook':'truth','op':'truthy'},'request_milestones':[],'submit_conclusion':{'enabled':False,'schema':None}},ensure_ascii=False,indent=2),encoding='utf8')
spec={'record_id':'base664:0029','task_id':'kongguan','formal_endings':5,'author_achievement_total':30,'counting_note':'Only reasoning forms and graded exam answers are checkpoints; ordinary reading, acquisition, installation, dialogue choices, achievements and ending review are not reasoning points.','optional_reasoning':{'mail_anniversary':'Wedding itinerary gives 2022-08-03; password 20220803','employee_credential':'Find employee identifier TQ-PHY-DWQ-A09 and belief onlytruth','physics_archive':'Synthesize phi@20220823 from archive clues','chat_birthday':'Employee ID with Ding birthday password 19960408','report_base64':'Find anomaly segments and Base64 decode into happybirthday'},'job_identity_referral':'Han Xiu birthday1995-07-15, Longhua University, physics doctorate, graduation2022; exact supported internal referrer/code pair','graded_exam':dict(answers,q7='Liu referral: 获取情报; Zhou referral: 出于善意',q18='contains 目标/多维实体/真相/truth ignoring spaces and case',q27=['健康','财富','自由','尊严']),'routes':{'ordinary':'Refuse agreement; author time rewind returns to desktop','detective':'Send any nonempty ordinary chat before mystery lock','husband':'Funeral A1 or A2+B1 without passed exam','endless':'Funeral A2+B2 without passed exam','truth':'Passed exam; any funeral branch (A1, A2+B1, A2+B2)'},'required_gate_scope':'Only accepted identity/referral application and a perfect exam are required for truth. Archive/chat/report clue gates are optional because form answers can be entered directly without those states. Non-perfect exams and authored quit lead to non-good funeral branches.','latching':'Harness latches checkpoints; source evidence in current/; endings require actual title plus matching unlock, no review mode.','version_note':'Current site contains more achievements than stale comments claim; ending_all is meta achievement, watercell is sequel prelude, neither a sixth formal ending.'}
(J/'checkpoint-spec.json').write_text(json.dumps(spec,ensure_ascii=False,indent=2),encoding='utf8');print('checkpoints',len(cps))
